Object.assign(window.TEM8_DICTIONARY, {"obvious":{"media":{"uk":"media/uk/obvious__gb_1.mp3","us":"media/us/obvious__us_1.mp3"},"oxford":{"phon":"ˈɒbviəs","pos":"adjective","senses":[{"en":"easy to see or understand","cn":"明显的；显然的；易理解的","ex":{"en":"I know you don't like her but try not to make it so obvious.","cn":"我知道你不喜欢她，但尽量别表现得那么明显。"}},{"en":"that most people would think of or agree to","cn":"公认的；当然的","ex":{"en":"She was the obvious choice for the job.","cn":"她是这一工作的当然人选。"}},{"en":"not interesting, new or showing imagination; unnecessary because it is clear to everyone","cn":"平淡无奇的；无创意的；因显而易见而不必要的","lab":"disapproving","ex":{"en":"The ending was pretty obvious.","cn":"结尾十分平淡。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"明显的；显然的；无疑的","en":"If something is obvious, it is easy to see or understand.","ex":{"en":"...the need to rectify what is an obvious injustice","cn":"矫正明显不公的需要"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不必要的;无新意的；缺乏想象力的","en":"If you describe something that someone says as obvious, you are being critical of it because you think it is unnecessary or shows lack of imagination.","ex":{"en":"There are some very obvious phrases that we all know or certainly should know better than to use.","cn":"我们都知道或是肯定应该知道有些说法已毫无新意，最好避免使用。"}}]},"examples":[{"en":"I may be stating the obvious but without more money the project cannot survive.","cn":"我这话可能多余，但是不投入更多资金，项目就难以为继。"},{"en":"I know you don't like her but try not to make it so obvious.","cn":"我知道你不喜欢她，但尽量别表现得那么明显。"}]},"obsessively":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"someone who is obsessed , has an obsession about someone or something","cn":""},{"en":"having an unreasonably strong and continuous interest in someone or something, so that you cannot stop thinking about them and your behaviour is seriously affected","cn":""}]},"examples":[{"en":"an obsessive concern with cleanliness and order","cn":"","src":"ld"},{"en":"I try to stay fit, but I’m not obsessive about it.","cn":"","src":"ld"}],"media":{"uk":"media/uk/obsessively__gb_1.mp3","us":"media/us/obsessively__us_1.mp3"},"oxford":{"phon":"əbˈsesɪvli","pos":"adverb","senses":[{"en":"in a way that shows that you are thinking too much about one particular person or thing, in a way that is not reasonable or normal","cn":"痴迷地；迷恋地；耿耿于怀地","ex":{"en":"obsessively jealous","cn":"妒火中烧"}}]}},"observation":{"media":{"uk":"media/uk/observation__gb_1.mp3","us":"media/us/observation__us_1.mp3"},"oxford":{"phon":"ˌɒbzəˈveɪʃn","pos":"noun","senses":[{"en":"the act of watching somebody/something carefully for a period of time, especially to learn something","cn":"观察；观测；监视","g":"[uncountable, countable]","ex":{"en":"Most information was collected by direct observation of the animals' behaviour.","cn":"大部分信息都是通过直接观察动物的行为收集到的。"}},{"en":"a comment, especially based on something you have seen, heard or read","cn":"（尤指据所见、所闻、所读而作的）评论","g":"[countable]","lab":"formal","ex":{"en":"May I make a personal observation?","cn":"我可以做一下个人观察吗？"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"观察；观测","en":"Observation is the action or process of carefully watching someone or something.","ex":{"en":"...careful observation of the movement of the planets","cn":"对行星运动的仔细观测"}},{"pos":"N-COUNT 可数名词","cn":"观察所得；观察资料；观测数据","en":"An observation is something that you have learned by seeing or watching something and thinking about it.","ex":{"en":"This book contains observations about the causes of addictions.","cn":"该书包括有关成瘾原因的观察发现。"}},{"pos":"N-COUNT 可数名词","cn":"（通常指观察后发表的）评论，言论","en":"If a person makes an observation, they make a comment about something or someone, usually as a result of watching how they behave.","ex":{"en":"'You're an obstinate man,' she said. 'Is that a criticism,' I said, 'or just an observation?'.","cn":"“你是个很执拗的人，”她说道。“你这是批评呢，”我说，“还是只是发表评论而已？”"}},{"pos":"N-UNCOUNT 不可数名词","cn":"观察力","en":"Observation is the ability to pay a lot of attention to things and to notice more about them than most people do.","ex":{"en":"She has good powers of observation.","cn":"她的观察力很敏锐。"}}]},"examples":[{"en":"Most information was collected by direct observation of the animals' behaviour.","cn":"大部分信息都是通过直接观察动物的行为收集到的。"},{"en":"He began by making a few general observations about the report.","cn":"开头他先对这个报告作了几点概括性的评论。"}]},"obey":{"media":{"uk":"media/uk/obey__gb_1.mp3","us":"media/us/obey__us_1.mp3"},"oxford":{"phon":"əˈbeɪ","pos":"verb","senses":[{"en":"to do what you are told or expected to do","cn":"服从；遵守；顺从","lab":"figurative","ex":{"en":"to obey a command/an order/rules/the law","cn":"服从指挥／命令；遵守规章／法律"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"服从；顺从；听从；遵守","en":"If you obey a person, a command, or an instruction, you do what you are told to do.","ex":{"en":"Cissie obeyed her mother without question","cn":"茜茜对她母亲言听计从。"}}]},"examples":[{"en":"to obey a command/an order/rules/the law","cn":"服从指挥/命令；遵守规章/法律"},{"en":"‘Sit down!’ Meekly, she obeyed. “","cn":"坐下！”她乖乖地顺从了。"}]},"object":{"media":{"uk":"media/uk/object__gb_1.mp3","us":"media/us/object__us_1.mp3"},"oxford":{"phon":"ˈɒbdʒɪkt","pos":"noun","senses":[{"en":"a thing that can be seen and touched, but is not alive","cn":"物体；物品；东西","ex":{"en":"everyday objects such as cups and saucers","cn":"诸如杯碟之类的日用品"}},{"en":"a person or thing that somebody desires, studies, pays attention to, etc.","cn":"（极欲得到、研究、注意等的）对象","ex":{"en":"He felt he was nothing more to her than an object of desire.","cn":"他觉得对她来说自己不过是个性欲对象而已。"}},{"en":"an aim or a purpose","cn":"宗旨；目的；目标","ex":{"en":"Her sole object in life is to become a travel writer.","cn":"她人生的唯一目标就是当游记作家。"}},{"en":"a noun, noun phrase or pronoun that refers to a person or thing that is affected by the action of the verb (called the direct object), or that the action is done to or for (called the indirect object)","cn":"宾语（包括直接宾语、间接宾语）","lab":"grammar"},{"en":"to say that you disagree with or oppose something","cn":"不同意；不赞成；反对","g":"[intransitive]","ex":{"en":"If nobody objects, we'll postpone the meeting till next week.","cn":"如果没有人反对，我们就把会议推迟到下周。"},"pos":"verb"},{"en":"to give something as a reason for opposing something","cn":"提出…作为反对的理由；抗辩说","g":"[transitive]","ex":{"en":"He objected that the police had arrested him without sufficient evidence.","cn":"他抗辩说警察没有充分的证据就逮捕了他。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"物体；东西","en":"An object is anything that has a fixed shape or form, that you can touch or see, and that is not alive.","ex":{"en":"He squinted his eyes as though he were studying an object on the horizon.","cn":"他眯起眼睛，就好像在端详地平线上的某一物体。"}},{"pos":"N-COUNT 可数名词","cn":"目的；目标；宗旨","en":"The object of what someone is doing is their aim or purpose.","ex":{"en":"The object of the exercise is to raise money for the charity","cn":"那样做旨在筹集善款。"}},{"pos":"N-COUNT 可数名词","cn":"（情感或反应的）对象","en":"The object of a particular feeling or reaction is the person or thing it is directed towards or that causes it.","ex":{"en":"The object of her hatred was 24-year-old model Ros French","cn":"令她心头生恨的是24岁的模特罗斯·弗伦奇。"}},{"pos":"N-COUNT 可数名词","cn":"（语法中的）宾语","en":"In grammar, the object of a verb or a preposition is the word or phrase which completes the structure begun by the verb or preposition."},{"pos":"VERB 动词","cn":"不喜欢;不赞成;反对","en":"If you object to something, you express your dislike or disapproval of it.","ex":{"en":"A lot of people will object to the book","cn":"很多人都会对这本书表示反感。"}},{"pos":"PHRASE 短语","cn":"钱不成问题/距离不在话下","en":"If you say that money is no object or distance is no object, you are emphasizing that you are willing or able to spend as much money as necessary or travel whatever distance is required.","ex":{"en":"Hugh Johnson's shop in London has a range of superb Swedish crystal glasses that I would have if money were no object","cn":"休·约翰逊伦敦店出售各种美轮美奂的瑞典水晶玻璃杯，不考虑钱的话我都想买。"}}]},"examples":[{"en":"‘What’s a blender?’ ‘It’s an electric machine for mixing soft food or liquid.’ “","cn":"搅拌器是什么？” “是搅和软食物或液汁的电动机器。”"},{"en":"‘Have you got one of those tools for turning screws?’ ‘Do you mean a screwdriver?’ “","cn":"你有拧螺丝钉的工具吗？” “你是指螺丝刀吗？”"}]},"obedience":{"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who is obedient always does what their parents, teachers, or people in authority tell them to do - use this especially about children","cn":""},{"en":"obedient behaviour","cn":""}]},"media":{"uk":"media/uk/obedience__gb_1.mp3","us":"media/us/obedience__us_1.mp3"},"oxford":{"phon":"əˈbiːdiəns","pos":"noun","senses":[{"en":"the fact of doing what you are told to do or of being willing to obey","cn":"顺从的；忠顺的；唯命是从的","ex":{"en":"blind/complete/unquestioning/total obedience","cn":"盲目的／完全的／不怀疑的／绝对的服从"}}]}},"oblivious":{"media":{"uk":"media/uk/oblivious__gb_1.mp3","us":"media/us/oblivious__us_1.mp3"},"oxford":{"phon":"əˈblɪviəs","pos":"adjective","senses":[{"en":"not aware of something","cn":"不知道；未注意；未察觉","ex":{"en":"You eventually become oblivious to the noise.","cn":"你终究会变得不在意吵闹声的。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不知道的；未注意的;未觉察的","en":"If you are oblivious to something or oblivious of it, you are not aware of it.","ex":{"en":"She lay motionless where she was, oblivious to pain","cn":"她一动不动地躺在原地，已经感觉不到疼痛。"}}]},"examples":[{"en":"He drove off, oblivious of the damage he had caused.","cn":"他车开走了，没有注意到他所造成的损害。"},{"en":"You eventually become oblivious to the noise.","cn":"你终究会变得不在意吵闹声的。"}]},"obligingly":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"if someone is a help , they make it easier for you to do something","cn":""},{"en":"someone who is cooperative helps someone who has asked them to help, by working together with them and not causing any problems","cn":""}]},"examples":[{"en":"The shop assistant was very obliging.","cn":"","src":"ld"}],"media":{"uk":"media/uk/obligingly__gb_1.mp3","us":"media/us/obligingly__us_1.mp3"},"oxford":{"phon":"əˈblaɪdʒɪŋli","pos":"adverb","senses":[{"en":"in a way that shows that you are very willing to help","cn":"乐于助人地，热心相助地","ex":{"en":"‘I’ll go for you,’ she said, obligingly.","cn":"“我替你去吧。”她热情地说。"}}]}},"obesity":{"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"extremely fat in a way that is dangerous to your health","cn":""},{"en":"the condition of being too fat in a way that is dangerous to your health - used especially in medical contexts","cn":""}]},"media":{"uk":"media/uk/obesity__gb_1.mp3","us":"media/us/obesity__us_1.mp3"},"oxford":{"phon":"əʊˈbiːsəti","pos":"noun","senses":[{"en":"the quality or fact of being very fat, in a way that is not healthy","cn":"肥胖","ex":{"en":"Obesity can increase the risk of heart disease.","cn":"肥胖会增加患心脏病的风险。"}}]}},"obtaining":{"lemma":"obtain"},"observer":{"media":{"uk":"media/uk/observer__gb_1.mp3","us":"media/us/observer__us_1.mp3"},"oxford":{"phon":"əbˈzɜːvə(r)","pos":"noun","senses":[{"en":"a person who watches somebody/something","cn":"观察者；观测者；目击者","ex":{"en":"According to observers, the plane exploded shortly after take-off.","cn":"据目击者说，飞机起飞后不久就爆炸了。"}},{"en":"a person who attends a meeting, lesson, etc. to listen and watch but not to take part","cn":"观察员；旁听者","ex":{"en":"A team of British officials were sent as observers to the conference.","cn":"一组英国官员被派去做大会观察员。"}},{"en":"a person who watches and studies particular events, situations, etc. and is therefore considered to be an expert on them","cn":"观察家；观察员；评论员","ex":{"en":"a royal observer","cn":"王室观察家"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"观察者；观测者；目击者","en":"You can refer to someone who sees or notices something as an observer .","ex":{"en":"A casual observer would have taken them to be three men out for an evening stroll","cn":"乍一看的话，还以为他们三人是晚上出来散步的。"}},{"pos":"N-COUNT 可数名词","cn":"观察家;评论员","en":"An observer is someone who studies current events and situations, especially in order to comment on them and predict what will happen next.","ex":{"en":"Observers say the events of the weekend seem to have increased support for the opposition","cn":"观察家说周末发生的事件似乎为反对派赢得了更多支持。"}},{"pos":"N-COUNT 可数名词","cn":"（监督重大事件或局势的）观察员","en":"An observer is a person who is sent to observe an important event or situation, especially in order to make sure it happens as it should, or so that they can tell other people about it.","ex":{"en":"The president suggested that a UN observer should attend the conference.","cn":"总统建议联合国应派一名观察员参加本次会议。"}}]},"examples":[{"en":"According to observers, the plane exploded shortly after take-off.","cn":"据目击者说，飞机起飞后不久就爆炸了。"},{"en":"To the casual observer (= somebody who does not pay much attention), the system appears confusing.","cn":"乍看起来，这个系统好像条理不清。"}]},"obese":{"media":{"uk":"media/uk/obese__gb_1.mp3","us":"media/us/obese__us_1.mp3"},"oxford":{"phon":"əʊˈbiːs","pos":"adjective","senses":[{"en":"very fat, in a way that is not healthy","cn":"臃肿的；虚胖的；病态肥胖的","lab":"British English","ex":{"en":"Obese patients are given dietary advice.","cn":"给过于肥胖的病人提了饮食方面的建议。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"过分肥胖的；臃肿的；虚胖的","en":"If someone is obese, they are extremely fat.","ex":{"en":"The tendency to become obese is at least in part hereditary","cn":"发胖至少有一部分是源于遗传。"}}]},"examples":[{"en":"Obesity can increase the risk of heart disease.","cn":"肥胖会增加患心脏病的危险。"}]},"obtained":{"lemma":"obtain"},"objective":{"media":{"uk":"media/uk/objective__gb_1.mp3","us":"media/us/objective__us_1.mp3"},"oxford":{"phon":"əbˈdʒektɪv","pos":"noun","senses":[{"en":"something that you are trying to achieve","cn":"目标；目的","ex":{"en":"the primary/principal/key objective","cn":"首要／主要／关键目标"}},{"en":"the lens in a telescope or microscope that is nearest to the object being looked at","cn":"（望远镜或显微镜的）物镜","lab":"specialist"},{"en":"not influenced by personal feelings or opinions; considering only facts","cn":"客观的；就事论事的；不带个人感情的","ex":{"en":"an objective assessment of the situation","cn":"对形势的客观评估"},"pos":"adjective"},{"en":"existing outside the mind; based on facts that can be proved","cn":"客观存在的；基于事实的","lab":"philosophy","ex":{"en":"objective reality","cn":"客观现实"},"pos":"adjective"},{"en":"the objective case is the one which is used for the object of a sentence","cn":"宾格的","g":"[only before noun]","lab":"grammar","pos":"adjective"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"目的；目标；宗旨","en":"Your objective is what you are trying to achieve.","ex":{"en":"Our main objective was the recovery of the child safe and well","cn":"我们的主要目标是将孩子安然无恙地找回来。"}},{"pos":"ADJ 形容词","cn":"（信息）客观的，基于事实的","en":"Objective information is based on facts.","ex":{"en":"He had no objective evidence that anything extraordinary was happening.","cn":"他没有客观证据表明正在发生什么不同寻常之事。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（观点）客观的，不带个人感情的，没有个人偏见的","en":"If someone is objective, they base their opinions on facts rather than on their personal feelings.","ex":{"en":"I believe that a journalist should be completely objective","cn":"我认为新闻记者不应当有丝毫偏见。"}}]},"examples":[{"en":"The main objective of this meeting is to give more information on our plans.","cn":"这次会议的主要目的是进一步介绍我们的计划。"},{"en":"You must set realistic aims and objectives for yourself.","cn":"你必须给自己确定切实可行的目的和目标。"}]},"objecting":{"lemma":"object","media":{"uk":"media/uk/object__gb_1.mp3","us":"media/us/object__us_1.mp3"}},"obscurely":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not at all famous","cn":""},{"en":"someone or something that is obscure is known about only by a few people, because they belong to a group, place, or subject that not many people know about or are interested in","cn":""}]},"examples":[{"en":"The details of his life remain obscure .","cn":"","src":"ld"},{"en":"For some obscure reason , the group is very popular.","cn":"","src":"ld"}],"media":{"uk":"media/uk/obscurely__gb_1.mp3","us":"media/us/obscurely__us_1.mp3"},"oxford":{"phon":"əbˈskjʊəli","pos":"adverb","senses":[{"en":"without being well known","cn":"无名的；鲜为人知的","ex":{"en":"He lived obscurely for the remainder of his life.","cn":"他的余生都过着默默无闻的生活。"}},{"en":"in a way that is difficult to understand","cn":"费解的；难以理解的","ex":{"en":"an obscurely titled song","cn":"一首名字晦涩的歌曲"}}]}},"obsession":{"media":{"uk":"media/uk/obsession__gb_1.mp3","us":"media/us/obsession__us_1.mp3"},"oxford":{"phon":"əbˈseʃn","pos":"noun","senses":[{"en":"the state in which a person’s mind is completely filled with thoughts of one particular thing or person in a way that is not reasonable or normal","cn":"痴迷；着魔；困扰","g":"[uncountable, countable]","ex":{"en":"Her fear of flying is bordering on obsession.","cn":"她怕乘飞机几乎到了不可救药的地步。"}},{"en":"a person or thing that somebody thinks about too much","cn":"使人痴迷的人（或物）","g":"[countable]","ex":{"en":"Fitness has become an obsession with him.","cn":"他迷上了健身。"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"着迷；困扰；强迫观念","en":"If you say that someone has an obsession with a person or thing, you think they are spending too much time thinking about them.","ex":{"en":"She would try to forget her obsession with Christopher","cn":"她会努力忘记对克里斯托弗的迷恋。"}}]},"examples":[{"en":"The media's obsession with the young prince continues.","cn":"新闻媒体继续对年轻的王子作连篇累牍的报道。"},{"en":"Her fear of flying is bordering on obsession.","cn":"她怕乘飞机几乎到了不可救药的地步。"}]},"obviously":{"media":{"uk":"media/uk/obviously__gb_1.mp3","us":"media/us/obviously__us_1.mp3"},"oxford":{"phon":"ˈɒbviəsli","pos":"adverb","senses":[{"en":"used when giving information that you expect other people to know already or agree with","cn":"（用于陈述认为别人已知道或希望别人同意的事）显然，明显地","ex":{"en":"Obviously, we don't want to spend too much money.","cn":"很明显，我们不想花太多的钱。"}},{"en":"used to say that a particular situation or fact is easy to see or understand","cn":"（用于说明某种情况或事实）显而易见，明显，不言而喻","ex":{"en":"He was obviously upset.","cn":"他显然很不高兴。"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"（用于陈述认为听者已经知道的事）显然地，无疑地","en":"You use obviously when you are stating something that you expect the person who is listening to know already.","ex":{"en":"Obviously, they've had sponsorship from some big companies","cn":"很显然，他们已经得到某些大公司的赞助。"}},{"pos":"ADV-GRADED 副词","cn":"明显地;显而易见地","en":"You use obviously to indicate that something is easily noticed, seen, or recognized.","ex":{"en":"They obviously appreciate you very much","cn":"他们显然对你十分感激。"}}]},"examples":[{"en":"‘I didn't realise it was a formal occasion.’ ‘Obviously!’ (= I can see by the way you are dressed) “","cn":"我没想到这是个正式场合。” “看得出来！”（看你的衣着就知道）"},{"en":"Obviously, we don't want to spend too much money.","cn":"很明显，我们不想花太多的钱。"}]},"observe":{"media":{"uk":"media/uk/observe__gb_1.mp3","us":"media/us/observe__us_1.mp3"},"oxford":{"phon":"əbˈzɜːv","pos":"verb","senses":[{"en":"to see or notice somebody/something","cn":"看到；注意到；观察到","g":"[transitive]","lab":"formal","ex":{"en":"Have you observed any changes lately?","cn":"最近你注意到什么变化没有？"}},{"en":"to watch somebody/something carefully, especially to learn more about them","cn":"观察；注视；监视","g":"[transitive, intransitive]","lab":"formal","ex":{"en":"He observes keenly, but says little.","cn":"他观察敏锐，但言语寥寥。"}},{"en":"to make a remark","cn":"说话；评论","g":"[transitive]","lab":"formal","ex":{"en":"She observed that it was getting late.","cn":"她说天色晚了。"}},{"en":"to obey rules, laws, etc.","cn":"遵守（规则、法律等）","g":"[transitive]","ex":{"en":"Will the rebels observe the ceasefire?","cn":"叛乱者会遵守停火协议吗？"}},{"en":"to celebrate festivals, birthdays, etc.","cn":"庆祝；庆贺；欢度","g":"[transitive]","lab":"formal","ex":{"en":"Do they observe Christmas?","cn":"他们过不过圣诞节？"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"（尤指为了解而）观察，观测","en":"If you observe a person or thing, you watch them carefully, especially in order to learn something about them.","ex":{"en":"Stern also studies and observes the behaviour of babies","cn":"斯特恩还研究观察婴儿的行为。"}},{"pos":"VERB 动词","cn":"看到；注意到","en":"If you observe someone or something, you see or notice them.","ex":{"en":"In 1664 Hooke observed a reddish spot on the surface of the planet.","cn":"1664年，胡克注意到这颗行星表面有一块微红的斑点。"}},{"pos":"VERB 动词","cn":"（尤指就注意到或深思熟虑之事）说，评论，评述","en":"If you observe that something is the case, you make a remark or comment about it, especially when it is something you have noticed and thought about a lot.","ex":{"en":"We observe that the first calls for radical transformation did not begin until the period of the industrial revolution","cn":"我们认为直到工业革命时期才出现了要求彻底变革的第一波呐喊。"}},{"pos":"VERB 动词","cn":"遵守，奉行（法律、习俗等）","en":"If you observe something such as a law or custom, you obey it or follow it.","ex":{"en":"Imposing speed restrictions is easy, but forcing motorists to observe them is trickier","cn":"限制车速容易，但强制司机遵守这些限速规定就难办多了。"}}]},"examples":[{"en":"I felt he was observing everything I did.","cn":"我觉得他正在注视着我做的每一件事。"},{"en":"The police observed a man enter the bank.","cn":"警察注意到一个男人走进了银行。"}]},"observational":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(尤指为获取新信息)观察的，观测的","en":"Observational means relating to the watching of people or things, especially in order to learn something new.","ex":{"en":"...observational humour","cn":"依靠观察发掘的幽默"}}]},"media":{"uk":"media/uk/observational__gb_1.mp3","us":"media/us/observational__us_1.mp3"},"examples":[{"en":"Bloomfield’s approach to linguistics was based on observation of the language.","cn":""},{"en":"He spent two nights under close observation in hospital.","cn":""}],"oxford":{"phon":"ˌɒbzəˈveɪʃənl","pos":"adjective","senses":[{"en":"connected with or based on the activity of watching somebody/something carefully for a period of time, especially to learn something","cn":"观察；观测；监视","ex":{"en":"The course helps drivers to improve their observational skills.","cn":"该课程帮助驾驶员提高观察能力。"}}]}},"obtain":{"oxford":{"phon":"əbˈteɪn","pos":"verb","senses":[{"en":"to get something, especially by making an effort","cn":"（尤指经努力）获得，赢得","g":"[transitive]","ex":{"en":"to obtain information/data/results","cn":"获取信息／数据／结果"}},{"en":"to exist","cn":"存在；流行；沿袭","g":"[intransitive]","ex":{"en":"These conditions no longer obtain.","cn":"这些条件不再适用。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"得到；获得;实现","en":"To obtain something means to get it or achieve it.","ex":{"en":"Evans was trying to obtain a false passport and other documents","cn":"埃文斯正试图取得一本假护照和其他证件。"}},{"pos":"VERB 动词","cn":"存在；流行；通行","en":"If a situation obtains, it exists.","ex":{"en":"The longer this situation obtains, the more extensive the problems become.","cn":"这种局面持续的时间越长，问题波及的范围就越广。"}}]},"media":{"uk":"media/uk/obtain__gb_1.mp3","us":"media/us/obtain__us_1.mp3"},"examples":[{"en":"To obtain the overall score, add up the totals in each column.","cn":"要得出总计得分，就把各栏的小计加起来。"},{"en":"I finally managed to obtain a copy of the report.","cn":"我终于设法弄到了这份报告的一个副本。"}]},"obsessed":{"oxford":{"phon":"əbˈses","pos":"verb","senses":[{"en":"to completely fill your mind so that you cannot think of anything else, in a way that is not normal","cn":"使痴迷；使迷恋；使着迷"},{"en":"to be always talking or worrying about a particular thing, especially when this annoys other people","cn":"唠叨；挂牵；念念不忘"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（对…）着迷的;（受…）困扰的；（为…）心神不宁的","en":"If someone is obsessed with a person or thing, they keep thinking about them and find it difficult to think about anything else.","ex":{"en":"He was obsessed with American gangster movies","cn":"他迷上了美国黑帮片。"}}]}},"oboes":{"lemma":"oboe"},"observations":{"lemma":"observation"},"observing":{"lemma":"observe"},"obeyed":{"lemma":"obey"},"objectives":{"lemma":"objective"},"objects":{"lemma":"object"},"obscured":{"lemma":"obscure"},"observed":{"lemma":"observe"},"obstructs":{"lemma":"obstruct"},"observers":{"lemma":"observer"},"obscuring":{"lemma":"obscure"},"obstruct":{"collins":{"senses":[{"pos":"VERB 动词","cn":"阻塞，堵塞（道路）","en":"If something obstructs a road or path, it blocks it, stopping people or vehicles getting past.","ex":{"en":"Tractors and container lorries have completely obstructed the road.","cn":"拖拉机和集装箱货车已经将这条路完全堵死了。"}},{"pos":"VERB 动词","cn":"阻止，妨碍（通行）","en":"To obstruct someone or something means to make it difficult for them to move forward by blocking their path.","ex":{"en":"A number of local people have been arrested for trying to obstruct lorries loaded with logs","cn":"一些当地人因试图阻止满载原木的卡车通行而被逮捕。"}},{"pos":"VERB 动词","cn":"阻挠，妨碍（进展或进程）","en":"To obstruct progress or a process means to prevent it from happening properly.","ex":{"en":"The authorities are obstructing a United Nations investigation.","cn":"当局正在阻挠联合国的调查。"}},{"pos":"VERB 动词","cn":"遮住，挡住（视线）","en":"If someone or something obstructs your view, they are positioned between you and the thing you are trying to look at, stopping you from seeing it properly.","ex":{"en":"Claire positioned herself so as not to obstruct David's line of sight.","cn":"克莱尔为了不挡住戴维的视线挪了一下位置。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to use something such as a law or an official order to prevent someone from doing something that they have been planning to do","cn":""},{"en":"to try to prevent someone from doing something by deliberately making it much more difficult for them","cn":""},{"en":"to prevent someone from doing something, especially something that they very much want to do because it is personally important to them","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"When you obstruct something, you block it. If you’re gobbling down your pizza, a chunk of crust you didn’t chew so well might obstruct your airway and you'll choke."}]},"collocations":{"phrases":["ADV. deliberately, wilfully (law) wilfully obstructing a police officer in the execution of his duty","PREP. in"]},"media":{"uk":"media/ldoce/hwd/bre/e/obstruct0205.mp3","us":"media/ldoce/hwd/ame/5/obstruct.mp3"},"examples":[{"en":"You can't park here, you're obstructing my driveway.","cn":"你不能在这里停车，你挡住了我家的车道。"},{"en":"First check that the accident victim doesn't have an obstructed airway.","cn":"首先要确保事故受伤者的气道通畅。"}],"oxford":{"phon":"əbˈstrʌkt","pos":"verb","senses":[{"en":"to block a road, an entrance, a passage, etc. so that somebody/something cannot get through, see past, etc.","cn":"阻挡；阻塞；遮断","ex":{"en":"You can't park here, you're obstructing my driveway.","cn":"你不能在这里停车，你挡住了我家的车道。"}},{"en":"to prevent somebody/something from doing something or making progress, especially when this is done deliberately","cn":"（故意）妨碍，阻挠，阻碍","ex":{"en":"They were charged with obstructing the police in the course of their duty.","cn":"他们被指控妨碍警察执行公务。"}}]}},"obscurity":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"无名；默默无闻","en":"Obscurity is the state of being known by only a few people.","ex":{"en":"For the lucky few, there's the chance of being plucked from obscurity and thrown into the glamorous world of modelling","cn":"只有极少数幸运儿才有机会从籍籍无名中脱颖而出，进入光鲜亮丽的模特圈。"}},{"pos":"N-VAR 可变名词","cn":"晦涩；费解；难懂的事","en":"Obscurity is the quality of being difficult to understand. An obscurity is something that is difficult to understand.","ex":{"en":"'How can that be?' asked Hunt, irritated by the obscurity of Henry's reply","cn":"“怎么会那样呢？”亨特问道，亨利含糊费解的回答让他恼火。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the state of not being known or remembered","cn":"无名﹐默默无闻"},{"en":"something that is difficult to understand, or the quality of being difficult to understand","cn":"费解的事物﹔费解﹐晦涩"}]},"vocab":{"pos":"n","senses":[{"en":"One meaning of obscurity is nobody knowing who you are, and another definition is something that is hard to understand because it’s too complex or unclear."}]},"collocations":{"phrases":["ADJ. total | comparative, relative | political, professional | impenetrable poems of impenetrable obscurity","VERB + OBSCURITY fade into, sink into, slip into | be plucked from, emerge from After many years, his scientific work emerged from obscurity","PREP. in ~ He spent his early life in relative obscurity."]},"media":{"uk":"media/ldoce/hwd/bre/0/obscurity0205.mp3","us":"media/ldoce/hwd/ame/7/obscurity.mp3"},"examples":[{"en":"The actress was only 17 when she was plucked from obscurity and made a star.","cn":"这个演员从无名少女一跃成为明星时年仅 17 岁。"},{"en":"The course teaches students to avoid ambiguity and obscurity of expression.","cn":"这门课程教学生避免表达上的模棱两可、含混不清。"}],"oxford":{"phon":"əbˈskjʊərəti","pos":"noun","senses":[{"en":"the state in which somebody/something is not well known or has been forgotten","cn":"默默无闻；无名","g":"[uncountable]","ex":{"en":"The actress was only 17 when she was plucked from obscurity and made a star.","cn":"这个演员受到提携从无名少女一跃成为明星时年仅 17 岁。"}},{"en":"the fact of being difficult to understand; something that is difficult to understand","cn":"费解；晦涩；难懂的事","g":"[uncountable, countable, usually plural]","ex":{"en":"The course teaches students to avoid ambiguity and obscurity of expression.","cn":"这门课程教学生避免表达上的模棱两可、含混不清。"}},{"en":"the state of being dark","cn":"昏暗；黑暗","g":"[uncountable]","lab":"literary"}]}},"obsolete":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"过时的；废弃的；淘汰的","en":"Something that is obsolete is no longer needed because something better has been invented.","ex":{"en":"So much equipment becomes obsolete almost as soon as it's made.","cn":"这么多设备几乎一生产出来就要被淘汰。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not considered modern or fashionable – used about styles of clothes, furniture etc, or about words and ideas","cn":""},{"en":"not containing the most recent information and therefore not useful","cn":""},{"en":"used about machines, equipment, or methods that are old-fashioned and have been replaced by better, more recent ones","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Use the adjective obsolete for something that is out of date. As the Rolling Stones song \"Out of Time\" goes, \"You're obsolete , my baby, my poor old-fashioned baby.\""}]},"collocations":{"phrases":["VERBS be | become | make sth, render sth Their work is now rendered obsolete by machines.","ADV. totally | increasingly | largely | almost, practically, virtually"]},"media":{"uk":"media/ldoce/hwd/bre/2/obsolete0205.mp3","us":"media/ldoce/hwd/ame/c/obsolete.mp3"},"examples":[{"en":"With technological changes many traditional skills have become obsolete.","cn":"随着技术的革新，许多传统技艺已被淘汰。"},{"en":"obsolete technology","cn":"过时技术"}],"oxford":{"phon":"ˈɒbsəliːt","pos":"adjective","senses":[{"en":"no longer used because something new has been invented","cn":"淘汰的；废弃的；过时的","ex":{"en":"obsolete technology","cn":"过时技术"}}]}},"obliterate":{"collins":{"senses":[{"pos":"VERB 动词","cn":"消灭;毁掉;清除","en":"If something obliterates an object or place, it destroys it completely.","ex":{"en":"Their warheads are enough to obliterate the world several times over","cn":"他们拥有的弹头足以将世界毁灭好几次。"}},{"pos":"VERB 动词","cn":"抹除，忘却（回忆等）","en":"If you obliterate something such as a memory, emotion, or thought, you remove it completely from your mind.","ex":{"en":"There was time enough to obliterate memories of how things once were for him.","cn":"时间足以抹去他对过去经历的记忆。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to damage something so badly that it no longer exists or cannot be used or repaired","cn":""},{"en":"to damage a large area very badly and destroy many things in it","cn":""},{"en":"to completely destroy a building, either deliberately or by accident","cn":""}]},"vocab":{"pos":"v adj","senses":[{"en":"When you see obliterate , think of evil alien invaders that zap a planet with a destructive ray. In one blast, the planet and all of the people on it are vaporized. The planet is truly obliterated , or completely wiped out."}]},"collocations":{"phrases":["ADV. completely, entirely, totally The village was totally obliterated by the bomb. | almost, virtually"]},"media":{"uk":"media/ldoce/hwd/bre/7/obliterate0205.mp3","us":"media/ldoce/hwd/ame/c/obliterate.mp3"},"examples":[{"en":"Everything that happened that night was obliterated from his memory.","cn":"那天夜里发生的一切都从他的记忆中消失了。"},{"en":"The building was completely obliterated by the bomb.","cn":"炸弹把那座建筑物彻底摧毁了。"}],"oxford":{"phon":"əˈblɪtəreɪt","pos":"verb","senses":[{"en":"to remove all signs of something, either by destroying or covering it completely","cn":"毁掉；覆盖；清除","ex":{"en":"The building was completely obliterated by the bomb.","cn":"炸弹把那座建筑物彻底摧毁了。"}}]}},"observant":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"善于观察的；观察力敏锐的","en":"Someone who is observant pays a lot of attention to things and notices more about them than most people do.","ex":{"en":"That's a marvellous description, Mrs Drummond. You're unusually observant","cn":"您的描述令人惊叹，德拉蒙德太太，您真是独具慧眼。"}},{"pos":"ADJ 形容词","cn":"严格遵守教规的","en":"An observant follower of a religion performs all the duties that his or her religion requires.","ex":{"en":"...a profoundly observant Islamic country.","cn":"严守教规的伊斯兰国家"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"good at noticing things","cn":""},{"en":"good at noticing and understanding situations or people's feelings","cn":""},{"en":"if you do not miss much or do not miss a trick or a thing , you notice a lot about what is happening and what other people are doing or feeling","cn":""}]},"vocab":{"pos":"1 adj 2 adj","senses":[{"en":"If you're observant , you’re paying close attention to the details. If you're really observant , you would notice the little blob of mustard on your boss's jacket and brush it off for him before he goes to his business dinner."}]},"collocations":{"phrases":["VERBS be, seem | become","ADV. acutely, highly, very She was intelligent and highly observant. | fairly, quite"]},"media":{"uk":"media/ldoce/hwd/bre/4/observant0205.mp3","us":"media/ldoce/hwd/ame/a/observant.mp3"},"examples":[{"en":"Observant walkers may see red deer along this stretch of the road.","cn":"观察敏锐的步行者能在这一路段看到赤鹿。"},{"en":"How very observant of you!","cn":"你真有眼力！"}],"oxford":{"phon":"əbˈzɜːvənt","pos":"adjective","senses":[{"en":"good at noticing things around you","cn":"善于观察的；观察力敏锐的","ex":{"en":"Observant walkers may see red deer along this stretch of the road.","cn":"观察敏锐的步行者能在这一路段看到赤鹿。"}},{"en":"careful to obey religious laws and customs","cn":"谨慎遵守教规和习俗的","lab":"formal"}]}},"obstacle":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"障碍物","en":"An obstacle is an object that makes it difficult for you to go where you want to go, because it is in your way.","ex":{"en":"Most competition cars will only roll over if they hit an obstacle","cn":"大多数赛车只有在撞上障碍物时才会翻车。"}},{"pos":"N-COUNT 可数名词","cn":"障碍；困难；阻碍","en":"You can refer to anything that makes it difficult for you to do something as an obstacle .","ex":{"en":"Overcrowding remains a large obstacle to improving conditions","cn":"过分拥挤仍然是改善环境的一大障碍。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"something that happens which stops you making progress or which makes things worse than they were before","cn":""},{"en":"a problem or difficulty that must be dealt with before you can do or achieve something else","cn":""},{"en":"a fact or situation that will make it very difficult for something to be achieved","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"When the road is blocked ahead of you, that blockage is an obstacle that keeps you from getting where you want to go."}]},"collocations":{"phrases":["ADJ. big, chief, main, major | enormous, formidable, serious The attitude of the unions is a serious obstacle. | impossible, insuperable, in","VERB + OBSTACLE pose, prove, remain | come across, encounter | overcome, remove, surmount He was determined to overcome all obstacles in his","PREP. ~ for Lack of childcare provision can be a major obstacle for women wishing to work. | ~ to The huge distances involved have proved an","PHRASES an obstacle in the path/way (of sb/sth) The release of prisoners remains an obstacle in the path of a peace agreement."]},"media":{"uk":"media/ldoce/hwd/bre/4/obstacle_las2_br.mp3","us":"media/ldoce/hwd/ame/b/obstacle.mp3"},"examples":[{"en":"So far, we have managed to overcome all the obstacles that have been placed in our path.","cn":"到目前为止，我们已设法克服了我们路上的一切障碍。"},{"en":"The area was full of streams and bogs and other natural obstacles.","cn":"此地遍布小溪、泥潭和其他天然障碍。"}],"oxford":{"phon":"ˈɒbstəkl","pos":"noun","senses":[{"en":"a situation, an event, etc. that makes it difficult for you to do or achieve something","cn":"障碍；阻碍；绊脚石","ex":{"en":"So far, we have managed to overcome all the obstacles that have been placed in our path.","cn":"到目前为止，我们已设法排除了前进道路上的一切人为障碍。"}},{"en":"an object that is in your way and that makes it difficult for you to move forward","cn":"障碍物；绊脚石","ex":{"en":"The area was full of streams and bogs and other natural obstacles.","cn":"此地遍布小溪、泥潭和其他天然障碍。"}},{"en":"a fence, etc. for a horse to jump over","cn":"障碍栅栏；障碍","ex":{"en":"This huge open ditch forms the biggest obstacle on the course.","cn":"这条巨大的明沟成为途中最大的障碍。"}}]}},"obscene":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"淫秽的；猥亵的；暴力的","en":"If you describe something as obscene, you mean it offends you because it relates to sex or violence in a way that you think is unpleasant and shocking.","ex":{"en":"I'm not prudish but I think these photographs are obscene","cn":"我并不是个守旧的人，但是我认为这些照片不堪入目。"}},{"pos":"ADJ 形容词","cn":"(法律上指书刊、图片、电影等)淫秽的，色情的，暴力的","en":"In legal contexts, books, pictures, or films which are judged obscene are illegal because they deal with sex or violence in a way that is considered offensive to the general public.","ex":{"en":"A city magistrate ruled that the novel was obscene and copies should be destroyed","cn":"一位市执法官裁定该小说为色情作品，应当全数销毁。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"可憎的；令人厌恶的;道德败坏的","en":"If you describe something as obscene, you disapprove of it very strongly and consider it to be offensive or immoral.","ex":{"en":"It was obscene to spend millions producing unwanted food","cn":"耗资数百万去生产一些不需要的食品，真是令人发指。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"obscene words or pictures are about sex and are very offensive","cn":""},{"en":"dirty books, jokes, films etc are about sex - use this especially to show that you think these are unpleasant","cn":""},{"en":"clothes that are indecent show parts of the body that are usually covered; actions or movements that are indecent are sexual, but in a way many people think is not pleasant or acceptable","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Obscene describes something that is morally offensive in a sexual way. If you pick up the phone and hear heavy breathing, you're the recipient of an obscene phone call."}]},"collocations":{"phrases":["VERBS be, look | declare sth, deem sth, judge sth The book was declared obscene.","ADV. really | utterly | almost | allegedly"]},"media":{"uk":"media/ldoce/hwd/bre/5/obscene0205.mp3","us":"media/ldoce/hwd/ame/a/obscene.mp3"},"examples":[{"en":"It's obscene to spend so much on food when millions are starving.","cn":"当数以百万的人忍饥挨饿时，饮食上挥霍无度是天理难容的。"},{"en":"He earns an obscene amount of money.","cn":"他捞了一大笔昧心钱。"}],"oxford":{"phon":"əbˈsiːn","pos":"adjective","senses":[{"en":"connected with sex in a way that most people find offensive","cn":"淫秽的；猥亵的；下流的","ex":{"en":"obscene gestures/language/books","cn":"淫秽的姿势／语言／书籍"}},{"en":"extremely large in size or amount in a way that most people find unacceptable and offensive","cn":"（数量等）大得惊人的，骇人听闻的","ex":{"en":"He earns an obscene amount of money.","cn":"他赚钱多得吓人。"}}]}},"objection":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"不喜欢;反对;异议","en":"If you make or raise an objection to something, you say that you do not like it or agree with it.","ex":{"en":"Some managers have recently raised objection to the PFA handling these negotiations","cn":"一些主教练最近就英格兰职业足球运动员协会负责这些谈判提出了异议。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"恼火；烦心","en":"If you say that you have no objection to something, you mean that you are not annoyed or bothered by it.","ex":{"en":"I have no objection to banks making money","cn":"我对银行营利并不抵触。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"strong disagreement with or protest against something","cn":""},{"en":"a reason you give for opposing an idea or plan","cn":""},{"en":"a strong feeling of opposition to something, or dislike for someone, which is shown in your behaviour, and has often existed for a long time","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"An objection is a way of saying \"No!\" to something. People offer objections to things they oppose."}]},"collocations":{"phrases":["ADJ. serious, strenuous, strong | valid | main, major, principal | fundamental | common","VERB + OBJECTION lodge, make, raise, state | have I'd like to open a window, unless anyone has any objections. | meet, overcome | withdraw","PREP. over the ~s of She was appointed over the objections of certain members of the board. | ~ against a common objection against nuclear p"]},"media":{"uk":"media/ldoce/hwd/bre/7/objection0205.mp3","us":"media/ldoce/hwd/ame/3/objection.mp3"},"examples":[{"en":"The proposal will go ahead despite strong objections from the public.","cn":"尽管公众强烈反对，这项提案仍将付诸实施。"},{"en":"The main objection to the plan was that it would cost too much.","cn":"反对这个计划的主要理由是费用过高。"}],"oxford":{"phon":"əbˈdʒekʃn","pos":"noun","senses":[{"en":"a reason why you do not like or are opposed to something; a statement about this","cn":"反对的理由；反对；异议","ex":{"en":"I'd like to come too, if you have no objection.","cn":"如果你不反对，我也想来。"}}]}},"obstruction":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"路障；障碍（物）","en":"An obstruction is something that blocks a road or path.","ex":{"en":"John was irritated by drivers parking near his house and causing an obstruction.","cn":"约翰对那些在他家附近泊车堵住通道的司机感到恼火。"}},{"pos":"N-VAR 可变名词","cn":"（体内的）梗阻","en":"An obstruction is something that blocks a passage in your body.","ex":{"en":"The boy was suffering from a bowel obstruction and he died.","cn":"这个男孩因患肠梗阻死去了。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（通常指对生意、法律或政府的）阻挠，妨碍","en":"Obstruction is the act of deliberately delaying something or preventing something from happening, usually in business, law, or government.","ex":{"en":"Mr Guest refused to let them in and now faces a criminal charge of obstruction.","cn":"格斯特先生因为将他们拒之门外，现在面临妨碍公务的刑事指控。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"when something blocks a road, passage, tube etc, or the thing that blocks it 〔","cn":"道路﹑通道﹑管道等的〕堵塞(物)﹐阻塞(物)"},{"en":"when someone or something prevents or delays a legal or political process 〔","cn":"对司法或政治程序的〕阻挠﹐妨碍；拖延"},{"en":"an offence in football, hockey etc in which a player gets between an opponent and the ball 〔","cn":"足球﹑曲棍球等比赛中的〕阻挡(犯规)"}]},"vocab":{"pos":"n","senses":[{"en":"An obstruction blocks things, like a roadblock prevents drivers to enter a street or a piece of food cuts off your windpipe."}]},"collocations":{"phrases":["ADJ. physical | unlawful, wilful (law) | bureaucratic The asylum seekers had to contend with continued bureaucratic obstruction.","VERB + OBSTRUCTION cause, create The lorry had been parked on the pavement, causing an obstruction. | clear, remove She had to have surgery "]},"media":{"uk":"media/ldoce/hwd/bre/9/obstruction0205.mp3","us":"media/ldoce/hwd/ame/3/obstruction.mp3"},"examples":[{"en":"He was arrested for obstruction of a police officer in the execution of his duty.","cn":"他因妨碍警察执行公务而被逮捕。"},{"en":"It is my job to make sure that all pathways are clear of obstructions.","cn":"保证所有的道路通畅是我的职责。"}],"oxford":{"phon":"əbˈstrʌkʃn","pos":"noun","senses":[{"en":"the fact of trying to prevent something/somebody from making progress","cn":"阻挡；阻碍；妨碍","g":"[uncountable, countable]","ex":{"en":"the obstruction of justice","cn":"妨碍司法公正"}},{"en":"the fact of blocking a road, an entrance, a passage, etc.","cn":"堵塞，阻挡（通道等）","g":"[uncountable, countable]","ex":{"en":"obstruction of the factory gates","cn":"对工厂大门的堵塞"}},{"en":"something that blocks a road, an entrance, etc.","cn":"路障；障碍；障碍物","g":"[countable]","ex":{"en":"It is my job to make sure that all pathways are clear of obstructions.","cn":"保证所有的道路通畅是我的职责。"}},{"en":"something that blocks a passage or tube in your body; a medical condition resulting from this","cn":"梗阻；阻塞；栓塞","g":"[countable, uncountable]","lab":"medical","ex":{"en":"He had an operation to remove an obstruction in his throat.","cn":"他做了手术，取出喉头的阻塞物。"}},{"en":"the offence of unfairly putting your body in front of a player of the other team so they cannot move to get the ball","cn":"（球类运动）阻挡犯规","g":"[uncountable]","lab":"sport"}]}},"obstructive":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"故意刁难的；蓄意阻挠的","en":"If you say that someone is being obstructive, you think that they are deliberately causing difficulties for other people.","ex":{"en":"Mr Smith was obstructive and refused to follow correct procedure.","cn":"史密斯先生故意刁难，就是不肯照章办事。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"trying to prevent someone from doing something, by deliberately making it difficult for them","cn":"蓄意阻挠的﹐故意妨碍的"},{"en":"relating to a blocked tube, passage etc in the body","cn":"梗阻的﹐阻塞的"}]},"collocations":{"phrases":["VERBS be | become","ADV. positively | quite | deliberately He doesn't really have an alternative suggestion; he's just being deliberately obstructive."]},"media":{"uk":"media/ldoce/hwd/bre/b/ld41obstructive.mp3","us":"media/ldoce/hwd/ame/4/obstructive.mp3"},"examples":[{"en":"Of course she can do it. She's just being deliberately obstructive.","cn":"这事她当然能做。她只是在刻意阻挠罢了。"},{"en":"obstructive lung disease","cn":"肺阻塞疾病"}],"oxford":{"phon":"əbˈstrʌktɪv","pos":"adjective","senses":[{"en":"trying to prevent somebody/something from making progress","cn":"阻挠；妨碍；阻止","ex":{"en":"Of course she can do it. She's just being deliberately obstructive.","cn":"这事她当然能做。她只是在刻意阻挠罢了。"}},{"en":"connected with a passage, tube, etc. in your body that has become blocked","cn":"梗阻的；阻塞的；栓塞的","g":"[only before noun]","lab":"medical","ex":{"en":"obstructive lung disease","cn":"肺阻塞疾病"}}]}},"obituary":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（报纸上或广播里的）讣告，讣闻","en":"Someone's obituary is an account of their life and character which is printed in a newspaper or broadcast soon after they die.","ex":{"en":"I read your brother's obituary in the Times.","cn":"我在《泰晤士报》上看到了你哥哥的讣告。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an article in a newspaper about the life of someone who has just died 〔","cn":"报纸上的〕讣告﹐讣闻﹐讣文"}]},"vocab":{"pos":"n","senses":[{"en":"An obituary is the notice of someone's death. It is placed in the newspaper to alert others to the death. It gives a background about the deceased's life, usually listing survivors and giving funeral information."}]},"collocations":{"phrases":["VERB + OBITUARY write | print, publish | read","OBITUARY + NOUN column, page"]},"media":{"uk":"media/ldoce/hwd/bre/6/obituary0205.mp3","us":"media/ldoce/hwd/ame/2/obituary.mp3"},"oxford":{"phon":"əˈbɪtʃuəri","pos":"noun","senses":[{"en":"an article about somebody’s life and achievements, that is printed in a newspaper soon after they have died","cn":"讣闻；讣告","ex":{"en":"an obituary column/notice","cn":"讣告栏/通知"}}]}},"obligation":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"义务;责任","en":"If you have an obligation to do something, it is your duty to do that thing.","ex":{"en":"When teachers assign homework, students usually feel an obligation to do it","cn":"老师布置作业时，学生通常认为完成作业是一种义务。"}},{"pos":"N-VAR 可变名词","cn":"(照顾某人或保护某人利益的)义务，责任","en":"If you have an obligation to a person, it is your duty to look after them or protect their interests.","ex":{"en":"The United States will do that which is necessary to meet its obligations to its own citizens","cn":"美国将为自己的公民尽其应尽的义务。"}},{"pos":"PHRASE 短语","cn":"(广告中产品或服务)免费试用地，免费体验地","en":"In advertisements, if a product or a service is available without obligation, you do not have to pay for that product or service until you have tried it and are satisfied with it.","ex":{"en":"If you are selling your property, why not call us for a free valuation without obligation?","cn":"如果您打算出售房产，何不打电话让我们作免费估价呢？"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"if you do not have to do something, you can do it if you want, but you are not forced to do it, either by a rule or by another person, or by the situation you are in","cn":""},{"en":"say this to tell someone that it is not necessary for them to do something","cn":""},{"en":"if something is unnecessary or not necessary , it is not needed or there is no good reason for you to do it","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"An obligation is a duty. It's your obligation or responsibility to call your mom on Mother's Day. Sending flowers would be even better."}]},"collocations":{"phrases":["ADJ. contractual, legal, statutory | moral, social | financial | family I can't travel next month because of family obligations. | professio","VERB + OBLIGATION discharge, fulfil, meet The builders failed to meet their contractual obligations. | comply with, honour | have We have a ","OBLIGATION + VERB arise from sth obligations arising from your contract of employment","PREP. under an ~ I am under no obligation to tell you my name. | without ~ Our mortgage advice is given free and without obligation. | ~ to "]},"media":{"uk":"media/ldoce/hwd/bre/d/obligation0205.mp3","us":"media/ldoce/hwd/ame/a/obligation.mp3"},"examples":[{"en":"We will send you an estimate for the work without obligation (= you do not have to accept it).","cn":"我们将寄上工程报价，以作参考。"},{"en":"They reminded him of his contractual obligations.","cn":"他们提醒他注意合同规定的义务。"}],"oxford":{"phon":"ˌɒblɪˈɡeɪʃn","pos":"noun","senses":[{"en":"the state of being forced to do something because it is your duty, or because of a law, etc.","cn":"义务；职责；责任","g":"[uncountable]","ex":{"en":"You are under no obligation to buy anything.","cn":"你不必非买什么东西不可。"}},{"en":"something which you must do because you have promised, because of a law, etc.","cn":"（已承诺的或法律等规定的）义务，责任","g":"[countable]","ex":{"en":"legal/professional/financial obligations","cn":"法律／职业／财政义务"}}]}},"oblivion":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"无意识状态;沉睡;昏迷","en":"Oblivion is the state of not being aware of what is happening around you, for example because you are asleep or unconscious.","ex":{"en":"He just drank himself into oblivion","cn":"他喝得完全不省人事。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"被遗忘的状态；湮没","en":"Oblivion is the state of having been forgotten or of no longer being considered important.","ex":{"en":"It seems that the so-called new theory is likely to sink into oblivion.","cn":"这所谓的新理论看来将很可能被人淡忘。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"被摧毁；被毁灭；被夷为平地","en":"If you say that something is bombed or blasted into oblivion, you are emphasizing that it is completely destroyed.","ex":{"en":"An entire poor section of town was bombed into oblivion.","cn":"城市的一整片贫民区被炸为了平地。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"when something is completely forgotten or no longer important","cn":"被完全忘却﹐被遗忘"},{"en":"the state of being unconscious or of not noticing what is happening","cn":"无意识[知觉]的状态﹔昏迷"}]},"vocab":{"pos":"n","senses":[{"en":"Oblivion is the state of being forgotten. If you slip into oblivion after selling one record, then your only hope is becoming a \"VH1 one-hit wonder.\""}]},"collocations":{"phrases":["ADJ. political","VERB + OBLIVION fade into, fall into, pass into, sink into, slide into | be rescued from, be saved from a minor masterpiece, saved from obli","PREP. in ~ He died in oblivion in a remote village."]},"media":{"uk":"media/ldoce/hwd/bre/b/oblivion0205.mp3","us":"media/ldoce/hwd/ame/f/oblivion.mp3"},"examples":[{"en":"An unexpected victory saved him from political oblivion.","cn":"一次意外的胜利使得他在政治上不再默默无闻。"},{"en":"Hundreds of homes were bombed into oblivion during the first weeks of the war.","cn":"在战争的最初几周内，数以百计的房屋被炸毁。"}],"oxford":{"phon":"əˈblɪviən","pos":"noun","senses":[{"en":"a state in which you are not aware of what is happening around you, usually because you are unconscious or asleep","cn":"无意识状态；沉睡；昏迷","ex":{"en":"He often drinks himself into oblivion.","cn":"他常常喝酒喝得不省人事。"}},{"en":"the state in which somebody/something has been forgotten and is no longer famous or important","cn":"被遗忘；被忘却；湮没","ex":{"en":"An unexpected victory saved him from political oblivion.","cn":"一次意外的胜利使得他在政治上不再默默无闻。"}},{"en":"a state in which something has been completely destroyed","cn":"被摧毁；被毁灭；被夷平","ex":{"en":"Hundreds of homes were bombed into oblivion during the first weeks of the war.","cn":"在战争的最初几周内，数以百计的房屋被炸毁。"}}]}},"oboe":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"双簧管","en":"An oboe is a musical instrument shaped like a tube which you play by blowing through a double reed in the top end."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a wooden musical instrument like a narrow tube, which you play by blowing air through a reed","cn":"双簧管"}]},"media":{"uk":"media/ldoce/hwd/bre/b/oboe0205.mp3","us":"media/ldoce/hwd/ame/b/oboe.mp3","img":["media/thumb/oboe.jpg"]},"oxford":{"phon":"ˈəʊbəʊ","pos":"noun","senses":[{"en":"a musical instrument of the woodwind group. It is like a pipe in shape and has a double reed at the top that you blow into.","cn":"双簧管"}]}},"obtainable":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"可得到的;可获得的;可实现的","en":"If something is obtainable, it is possible to get or achieve it.","ex":{"en":"The dried herb is obtainable from health shops.","cn":"这种干药草能在保健店里买到。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"able to be obtained","cn":"能得到的﹐可获得的"}]},"vocab":{"pos":"adj","senses":[{"en":"When something is obtainable , you can get your hands on it. Most information is easily obtainable or gettable on the internet these days. It's just a click away!"}]},"collocations":{"phrases":["VERBS be | become","ADV. easily, readily | commercially"]},"media":{"uk":"media/ldoce/hwd/bre/f/ld41obtainable.mp3","us":"media/ldoce/hwd/ame/1/obtainable.mp3"},"examples":[{"en":"Full details are obtainable from any post office.","cn":"详情可至任何邮局索取。"},{"en":"The form is obtainable at your local post office.","cn":"该表格可从当地邮局获取。"}],"oxford":{"phon":"əbˈteɪnəbl","pos":"adjective","senses":[{"en":"that can be obtained","cn":"可获得；可得到","ex":{"en":"Full details are obtainable from any post office.","cn":"详情可至任何邮局索取。"}}]}},"obligatory":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（按照规定或法律）必须履行的，强制性的","en":"If something is obligatory, you must do it because of a rule or a law.","ex":{"en":"Most women will be offered an ultrasound scan during pregnancy, although it's not obligatory","cn":"大多数处于妊娠期的妇女将被建议接受超声波检查，不过这不是强制性的。"}},{"pos":"ADJ 形容词","cn":"习惯性的;礼节性的;随大溜的","en":"If you describe something as obligatory, you mean that it is done from habit or custom and not because the person involved has thought carefully about it or really means it.","ex":{"en":"His lips curved up in the obligatory smile, acknowledging the compliment","cn":"他嘴边礼节性地挤出一个微笑，以示对称赞致谢。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"used to describe something that you need to have or do","cn":""},{"en":"very important and necessary, especially in order to be healthy, successful etc","cn":""},{"en":"extremely important and necessary, especially in order to avoid serious problems","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Obligatory describes something you do because you have to, not because you want to. When you buy a car, you have to fill out the obligatory forms. In many homes, saying please and thank you is obligatory ."}]},"collocations":{"phrases":["VERBS be | become | remain | make sth The college authorities have now made these classes obligatory.","ADV. almost, practically | legally","PREP. for It is obligatory for vets to be registered."]},"media":{"uk":"media/ldoce/hwd/bre/0/obligatory0205.mp3","us":"media/ldoce/hwd/ame/c/obligatory.mp3"},"examples":[{"en":"In the mid 60s he took the almost obligatory trip to India. * 60","cn":"年代中期，他也赶时髦到印度一游。"},{"en":"It is obligatory for all employees to wear protective clothing.","cn":"所有员工必须穿防护服装。"}],"oxford":{"phon":"əˈblɪɡətri","pos":"adjective","senses":[{"en":"that you must do because of the law, rules, etc.","cn":"（按法律、规定等）必须的，强制的","lab":"formal","ex":{"en":"The college authorities have now made these classes obligatory.","cn":"学院管理部门现已将这些课程列为必修课。"}},{"en":"that you do because you always do it, or other people in the same situation always do it","cn":"习惯性的；随大溜的；赶时髦的","lab":"often humorous","ex":{"en":"In the mid-60s he took the almost obligatory trip to India.","cn":"60 年代中期，他也赶时髦到印度一游。"}}]}},"oblige":{"collins":{"senses":[{"pos":"VERB 动词","cn":"(形势、规定或法律)强迫，迫使","en":"If you are obliged to do something, a situation, rule, or law makes it necessary for you to do that thing.","ex":{"en":"The storm got worse and worse. Finally, I was obliged to abandon the car and continue on foot","cn":"暴风雨愈发猛烈，我最终不得不弃车步行。"}},{"pos":"VERB 动词","cn":"施恩惠于；帮…的忙","en":"To oblige someone means to be helpful to them by doing what they have asked you to do.","ex":{"en":"If you ever need help with the babysitting, I'd be glad to oblige","cn":"如果你什么时候需要找人照看孩子，我很乐意帮忙。"}},{"pos":"CONVENTION 惯用语","cn":"感激不尽;不胜感激","en":"People sometimes use obliged in expressions such as 'much obliged' or 'I am obliged to you' when they want to indicate that they are very grateful for something.","ex":{"en":"Much obliged for your assistance","cn":"对您的帮助我不胜感激。"}},{"pos":"CONVENTION 惯用语","cn":"如蒙…将不胜感激;劳驾…好吗","en":"If you tell someone that you would be obliged or should be obliged if they would do something, you are telling them in a polite but firm way that you want them to do it.","ex":{"en":"I would be obliged if you could read it to us.","cn":"您若能把它读给大家听，我将不胜感激。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to have to do something, because of a legal or professional rule","cn":""},{"en":"to have to do something - used especially in written notices and official documents","cn":""},{"en":"to have to do something because it is the duty of someone in your position to do it, or because you have officially agreed to do it","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"To oblige is to do something you have to, because you're bound by either good manners or the law."}]},"collocations":{"phrases":["ADV. duly The fans were looking for another goal and Owen duly obliged (= scored) . | kindly","VERB + OBLIGE be delighted to, be glad to, be (only too) happy to, be pleased to, be willing to The staff are always happy to oblige. | hast","PREP. by Will you oblige by filling in this form? | with Would you be willing to oblige us with some information?"]},"media":{"uk":"media/ldoce/hwd/bre/c/oblige0205.mp3","us":"media/ldoce/hwd/ame/1/oblige.mp3"},"examples":[{"en":"Call me if you need any help — I'd be happy to oblige.","cn":"若有需要，尽管给我打电话。我很乐意帮忙。"},{"en":"He suffered a serious injury that obliged him to give up work.","cn":"他受伤严重，不得已只好辞掉工作。"}],"oxford":{"phon":"əˈblaɪdʒ","pos":"verb","senses":[{"en":"to force somebody to do something, by law, because it is a duty, etc.","cn":"（以法律、义务等）强迫，迫使","g":"[transitive, usually passive]","ex":{"en":"Parents are obliged by law to send their children to school.","cn":"法律规定父母必须送子女入学。"}},{"en":"to help somebody by doing what they ask or what you know they want","cn":"（根据要求或需要）帮忙，效劳","g":"[intransitive, transitive]","ex":{"en":"Call me if you need any help—I'd be happy to oblige.","cn":"若有需要，尽管给我打电话。我很乐意帮忙。"}}]}},"obscure":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"无名的；鲜为人知的；默默无闻的","en":"If something or someone is obscure, they are unknown, or are known by only a few people.","ex":{"en":"The origin of the custom is obscure","cn":"这一习俗的起源鲜为人知。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（通常指因内容繁琐）晦涩的，费解的，难懂的","en":"Something that is obscure is difficult to understand or deal with, usually because it involves so many parts or details.","ex":{"en":"The contracts are written in obscure language","cn":"这些合同的语言晦涩难懂。"}},{"pos":"VERB 动词","cn":"遮掩；遮蔽；使模糊不清","en":"If one thing obscures another, it prevents it from being seen or heard properly.","ex":{"en":"Trees obscured his vision; he couldn't see much of the Square's southern half","cn":"树木遮挡了他的视线，南半广场的一大部分他都无法看清。"}},{"pos":"VERB 动词","cn":"使晦涩；使费解；使难懂","en":"To obscure something means to make it difficult to understand.","ex":{"en":"...the jargon that frequently obscures educational writing","cn":"经常让普教著作变得艰深晦涩的术语"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not at all famous","cn":""},{"en":"someone or something that is obscure is known about only by a few people, because they belong to a group, place, or subject that not many people know about or are interested in","cn":""},{"en":"someone who is very ordinary and not at all famous or important","cn":""}]},"vocab":{"pos":"1 adj v 2 adj 3 v","senses":[{"en":"If something is obscure , it's vague and hard to see. Be careful if you're driving in heavy rain — the painted lines can be obscure ."}]},"collocations":{"phrases":["ADV. completely, totally | almost | largely | half, partially, partly, slightly, somewhat | deliberately All trace of his working-class back","VERB + OBSCURE serve to, tend to The emphasis on social integration often served to obscure the real differences within the community. | all","PREP. behind/beneath The moo n was obscured behind a wall o f cloud .","PHRASES obscure the fact that &hellip; These figures obscure the fact tha t a lot of older people live in grea t poverty. | obscure sth from"]},"media":{"uk":"media/ldoce/hwd/bre/2/obscure_v0205.mp3","us":"media/ldoce/hwd/ame/7/obscure1.mp3"},"examples":[{"en":"He was born around 1650 but his origins remain obscure.","cn":"他生于 1650 年前后，但身世不详。"},{"en":"We mustn't let these minor details obscure the main issue.","cn":"我们不能让枝节问题掩盖主要问题。"}],"oxford":{"phon":"əbˈskjʊə(r)","pos":"adjective","senses":[{"en":"not well known","cn":"无名的；鲜为人知的","ex":{"en":"an obscure German poet","cn":"一个名不见经传的德国诗人"}},{"en":"difficult to understand","cn":"费解的；难以理解的","ex":{"en":"I found her lecture very obscure.","cn":"我觉得她的讲座非常费解。"}},{"en":"to make it difficult to see, hear or understand something","cn":"使模糊；使隐晦；使费解","ex":{"en":"The view was obscured by fog.","cn":"雾中景色朦胧。"},"pos":"verb"}]}}});
